import React, { Fragment, useEffect } from 'react'
import {CgMouse} from 'react-icons/cg';
import './Home.css';
import ProductCard from './ProductCard.js';
import MetaData from '../layout/MetaData.js';
import axios from 'axios';
import { useDispatch,useSelector } from 'react-redux';
import { allProductRequest,allProductFail, allProductSuccess } from '../../features/productSlice.js';
import Loader from '../layout/Loader/Loader.js';
import { toast,ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const stylesForAlert={
    position: "top-right",
    autoClose: 3000,
    hideProgressBar: false,
    closeOnClick: true,
    pauseOnHover: true,
    draggable: true,
    theme: "dark",
};

function Home() {

    const dispatch=useDispatch();

    //import data from redux store
    const allProducts=useSelector((state)=>state.products.items) || [];
    const loading=useSelector((state)=>state.products.loading);

    // console.log(allProducts,loading,error);

    useEffect(()=>{

        const fatchProduct=async()=>{
            try {
                //fatch data from backend
                dispatch(allProductRequest());
                const response=await axios.get(`${process.env.REACT_APP_BACKEND_URL}/api/v1/products`);
                const products=response?.data?.data;
                
                //send data to the redux store
                dispatch(allProductSuccess(products));
 
            } catch (err) {
                // console.log(error.response.data.message);
                dispatch(allProductFail(err.response?.data?.message));
                toast.error(err.response?.data?.message,stylesForAlert);
            }
        }

        fatchProduct();

    },[dispatch]);

  return (
    <Fragment>
    <ToastContainer /> 
        {
            loading?(<Loader/>): 

            (<Fragment>

                <MetaData title="ECOMMERCE" />
        
                <div className="banner">
                    <p>Welcome to Shop Today!</p>
                     <h1>FIND AMAZING PRODUCT BELOW</h1> 
        
                    <a href="#container">
                        <button>
                            scroll <CgMouse/>
                        </button>
                    </a>
                </div>
        
                <h2 className="homeHeading"> Featured Products </h2>
        
                <div className="container" id="container">
        
                    {
                        allProducts.map((product)=>{
                            return ( <ProductCard key={product._id} product={product} />)
                        })
                    }
        
                </div>
        
            </Fragment>)
        }
    </Fragment>
  )
}

export default Home